<?php require __DIR__.'/../includes/bootstrap.php'; admin_required();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=normalize_phone($_POST['phone']??'');$email=trim($_POST['email']??'');if($name&&$phone){$id=client_id_by_contact($name,$phone,$email?:null);header('Location: client.php?id='.$id);exit;}}
